import {useEffect, useMemo, useRef, useState} from "react"

import {stagedFilesToParts, useComposerAttachments} from "@agenta/chat/hooks"
import {useToolConnectionsQuery} from "@agenta/entities/gatewayTool"
import {
    agentIconAtomFamily,
    agentTemplateByKey,
    agentTemplatesAtom,
    agentTemplatesStatusAtom,
    refetchAgentTemplatesAtom,
    workflowMolecule,
} from "@agenta/entities/workflow"
import {classifyAgentIntent} from "@agenta/shared/analytics"
import {isToolsEnabled, isWalletsEnabled} from "@agenta/shared/api/env"
import {loadAgentIconCatalog} from "@agenta/ui/agent-icon"
import {useAtomValue, useSetAtom, useStore} from "jotai"
import {useRouter} from "next/router"

import {capture, captureIntent} from "@/features/analytics/client"
import {newId} from "@/lib/ids"

import {useNewAgentAction} from "../agents/useNewAgentAction"

import {connectedApps} from "./onboardingApps"
import type {OnboardingCatalog} from "./onboardingChoices"
import {draftConfigurationAtom, onboardingConfiguration} from "./onboardingConfig"
import {
    onboardingDraftKey,
    type FirstAgentInput,
    type OnboardingDraft,
    type OnboardingIconPick,
} from "./onboardingDraft"
import {OnboardingFlow} from "./OnboardingFlow"
import {endOnboarding, isOnboardingPending} from "./onboardingPending"
import {personProperties, signupSurveyProperties} from "./onboardingQuestions"
import {isFixedStep, onboardingSteps, stepIndex, type OnboardingStep} from "./onboardingRoute"
import {useOnboardingModel} from "./useOnboardingModel"
import {useSeedToolConnections} from "./useSeedToolConnections"

/** Wires the flow to the draft agent, the catalog, analytics, and the shared create path. */
export const OnboardingFlowHost = ({
    base,
    projectId,
    entityId,
    userId,
    userEmail,
    homeUrl,
}: {
    base: string
    projectId: string
    /** The local draft agent Create commits; `null` while it is still being minted. */
    entityId: string | null
    userId: string | null
    /** Answers the signup survey's email question. */
    userEmail: string | null
    /** Where Skip leads. */
    homeUrl: string
}) => {
    // Without a pending mark the page is a preview: no analytics and no tool seeding.
    const [preview] = useState(() => !userId || !isOnboardingPending(userId))
    const router = useRouter()
    const templates = useAtomValue(agentTemplatesAtom)
    const templatesStatus = useAtomValue(agentTemplatesStatusAtom)
    const refetchTemplates = useSetAtom(refetchAgentTemplatesAtom)
    const catalog = useMemo<OnboardingCatalog>(
        () => ({templates, status: templatesStatus, retry: () => refetchTemplates()}),
        [templates, templatesStatus, refetchTemplates],
    )
    const autoModel = useOnboardingModel(entityId, projectId)
    // The wallet is behind its own flag; without it the credits step offers only a plan or a key.
    const walletsEnabled = useMemo(() => isWalletsEnabled(), [])
    const model = useMemo(
        () => (walletsEnabled ? autoModel : {...autoModel, credits: null}),
        [walletsEnabled, autoModel],
    )
    const steps = useMemo(() => onboardingSteps(), [])
    const configuration = useAtomValue(useMemo(() => draftConfigurationAtom(entityId), [entityId]))
    const updateConfiguration = useSetAtom(workflowMolecule.actions.updateConfiguration)
    const toolsEnabled = useMemo(() => isToolsEnabled(), [])
    const connectionsQuery = useToolConnectionsQuery()
    const {connections} = connectionsQuery
    const apps = useMemo(() => connectedApps(connections), [connections])
    useSeedToolConnections({
        enabled: toolsEnabled && !preview,
        connections,
        loaded: !connectionsQuery.isLoading && !connectionsQuery.error,
    })
    const newAgent = useNewAgentAction(base)
    // Files stage against a session id before the agent exists, as on Home.
    const [sessionId] = useState(newId)
    const attachments = useComposerAttachments({sessionId})
    const store = useStore()
    const draftKey = onboardingDraftKey(userId ?? "anonymous")
    const track = (event: string, properties?: Record<string, unknown>) => {
        if (!preview) capture(event, properties)
    }

    const startedRef = useRef(false)
    useEffect(() => {
        if (preview || startedRef.current) return
        startedRef.current = true
        capture("onboarding_started")
    }, [preview])

    const applyIcon = async (appId: string, pick: OnboardingIconPick) => {
        const glyph = (await loadAgentIconCatalog()).find((item) => item.name === pick.icon)
        if (glyph) {
            await store.set(agentIconAtomFamily(appId), {
                icon: glyph.name,
                color: pick.color,
                path: glyph.path,
            })
        }
    }

    const onStepCompleted = (step: OnboardingStep, draft: OnboardingDraft) => {
        track("onboarding_step_completed", {
            step: stepIndex(step) + 1,
            step_key: step,
            $set: personProperties(draft.answers),
        })
        if (step === steps.findLast((shown) => !isFixedStep(shown))) {
            track("survey sent", signupSurveyProperties(draft.answers, userEmail))
        }
    }

    const trackIntent = (templateKey: string | null, firstMessage: string) => {
        if (preview) return
        const template = templateKey ? agentTemplateByKey(templates, templateKey) : undefined
        if (template) {
            captureIntent({
                source: "template",
                properties: {
                    template: template.name,
                    templateId: template.key,
                    templateCategory: template.category,
                    surface: "onboarding",
                },
                intentValue: template.category || template.name,
            })
        } else {
            captureIntent({source: "composer", intentValue: classifyAgentIntent(firstMessage)})
        }
    }

    const onCreate = async ({
        name,
        firstMessage,
        icon,
        apps: chosenApps,
        templateKey,
    }: FirstAgentInput) => {
        if (!entityId) return false
        updateConfiguration(
            entityId,
            onboardingConfiguration(configuration ?? {}, {apps: chosenApps, connections}),
        )
        track("onboarding_create_clicked")
        trackIntent(templateKey ?? null, firstMessage)
        const staged = attachments.files
        const parts = staged.length > 0 ? stagedFilesToParts(staged, sessionId) : undefined
        // Cleared before the hand-off: the chat route seeds its tray from this session's store.
        attachments.clearAttachments(staged.map((file) => file.uid))
        // A template's package sets its own name, instructions, tools, trigger and model.
        const created = await newAgent.createFromPrompt({
            text: firstMessage,
            // Empty for a blank start: the create core's default, which the agent renames from its task.
            name: name || undefined,
            entityId,
            templateKey: templateKey ?? undefined,
            sessionId,
            parts,
            onCreated: (agent) => {
                if (userId) endOnboarding(userId)
                track("onboarding_agent_created", {revision_id: agent.revisionId})
                void applyIcon(agent.appId, icon).catch(() => undefined)
            },
        })
        if (!created) attachments.restoreAttachments(staged)
        return created
    }

    const onSkip = () => {
        track("onboarding_skipped", {step: stepIndex("templates") + 1, step_key: "templates"})
        if (!preview) captureIntent({source: "skipped"})
        if (userId) endOnboarding(userId)
        void router.replace(homeUrl)
    }

    return (
        <OnboardingFlow
            onboardingPath={`${base}/onboarding`}
            draftKey={draftKey}
            steps={steps}
            catalog={catalog}
            model={model}
            connectedApps={apps}
            creating={newAgent.creating}
            error={newAgent.error}
            attachments={attachments}
import {onboardingDraftKey, saveOnboardingDraft} from "./onboardingDraft"

/** Set at sign-up for a new account; while it stands, Home sends that user to onboarding. */
const onboardingPendingKey = (userId: string) => `agenta:onboarding:pending:${userId}`

/**
 * Written instead when the profile could not load right after sign-up, so the user id is not
 * known yet. The first user read within the window claims it; after that it is ignored, so a
 * stale one never sends a later account on the same browser to onboarding.
 */
const UNOWNED_PENDING_KEY = "agenta:onboarding:pending:unowned"
export const UNOWNED_PENDING_MAX_AGE_MS = 10 * 60 * 1000

/** `null` user id: the profile is not available yet, so the mark waits to be claimed. */
export const markOnboardingPending = (userId: string | null, at: number = Date.now()) => {
    try {
        window.localStorage.setItem(
            userId ? onboardingPendingKey(userId) : UNOWNED_PENDING_KEY,
            String(at),
        )
    } catch {
        // Storage restrictions only cost the redirect, never the sign-in.
    }
}

/** Moves a fresh unowned mark onto this user; drops a stale one. */
const claimUnownedPending = (userId: string, now: number) => {
    const at = Number(window.localStorage.getItem(UNOWNED_PENDING_KEY))
    if (!at) return
    window.localStorage.removeItem(UNOWNED_PENDING_KEY)
    if (now - at <= UNOWNED_PENDING_MAX_AGE_MS) {
        window.localStorage.setItem(onboardingPendingKey(userId), String(at))
    }
}

export const isOnboardingPending = (userId: string, now: number = Date.now()): boolean => {
    try {
        claimUnownedPending(userId, now)
        return window.localStorage.getItem(onboardingPendingKey(userId)) !== null
    } catch {
        return false
    }
}

export const clearOnboardingPending = (userId: string) => {
    try {
        window.localStorage.removeItem(onboardingPendingKey(userId))
    } catch {
        // Nothing to clear when storage is unavailable.
    }
}

/** Create or Skip: the user is done with onboarding, so its mark and answers go. */
export const endOnboarding = (userId: string) => {
    clearOnboardingPending(userId)
    saveOnboardingDraft(onboardingDraftKey(userId), null)
}

/** Home's move on a pending mark: wait for the answer, start onboarding, or dismiss it. */
export type PendingOnboarding = "none" | "wait" | "start" | "dismiss"

export interface PendingOnboardingInput {
    /** The signed-in user's mark; `null` while the user is still loading. */
    pending: boolean | null
    agentCount: number
    agentsPending: boolean
    agentsError: boolean
}

export const resolvePendingOnboarding = ({
    pending,
    agentCount,
    agentsPending,
    agentsError,
}: PendingOnboardingInput): PendingOnboarding => {
    if (pending === false) return "none"
    if (pending === null) return "wait"
    if (agentCount > 0) return "dismiss"
    // A failed list is not an empty project; Home is where it can be retried.
    if (agentsError) return "none"
    return agentsPending ? "wait" : "start"
}
    const refetchTemplates = useSetAtom(refetchAgentTemplatesAtom)
    // Existing users only (they have an agent), once per new release, unless they opted out.
    const openWhatsNew = useSetAtom(whatsNewAtom)
    const agentsSettled = !agentsQuery.isPending && !agentsQuery.isError
    const hasAgents = agents.length > 0
    const whatsNewCheckedRef = useRef(false)
    useEffect(() => {
        if (!agentsSettled || whatsNewCheckedRef.current) return
        whatsNewCheckedRef.current = true
        // Called for new users too: the first call seeds what already shipped as seen.
        const unseen = getUnseenReleases()
        if (hasAgents && unseen.length > 0 && !isWhatsNewOptedOut()) openWhatsNew({})
    }, [agentsSettled, hasAgents, openWhatsNew])
    const router = useRouter()
    const profile = useProfile()
    const userId = profile.user?.id ?? null
    const pendingOnboarding = resolvePendingOnboarding({
        pending: profile.isPending ? null : userId !== null && isOnboardingPending(userId),
        agentCount: agents.length,
        agentsPending: agentsQuery.isPending,
        agentsError: agentsQuery.isError,
    })
    useEffect(() => {
        if (pendingOnboarding === "start") void router.replace(`${base}/onboarding`)
        if (pendingOnboarding === "dismiss" && userId) clearOnboardingPending(userId)
    }, [pendingOnboarding, base, userId, router])
    const surface =
        pendingOnboarding === "wait" || pendingOnboarding === "start"
            ? "loading"
            : resolveHomeSurface({
                  agentCount: agents.length,
                  isPending: agentsQuery.isPending,
                  isError: agentsQuery.isError,
              })

    // Newest first. The list arrives in whatever order the query returns, which put agents made
    // months ago above one created a minute earlier — and the head of this list is also what the
    // composer binds by default.
    const listAgents = useMemo<HomeListAgent[]>(
        () =>
            [...agents]
                .sort(
                    (a, b) => Date.parse(b.created_at ?? "") - Date.parse(a.created_at ?? "") || 0,
                )
                .map((agent) => ({
                    id: agent.id,
                    name: agent.name || agent.slug || "Untitled agent",
                    description: agent.description,
                })),
        [agents],
    )

import type {OnboardingDraft} from "./onboardingDraft"
import {answerLabels, ONBOARDING_QUESTIONS, type OnboardingQuestionId} from "./onboardingQuestions"

/** The steps after the questions, always shown. */
const FIXED_STEPS = ["credits", "templates"] as const
type FixedStep = (typeof FIXED_STEPS)[number]

export type OnboardingStep = OnboardingQuestionId | FixedStep

/** The steps this flow shows, in order. */
export type OnboardingSteps = readonly OnboardingStep[]

export const isFixedStep = (step: string): step is FixedStep =>
    (FIXED_STEPS as readonly string[]).includes(step)

/** Every registry question, shown or not, then the fixed steps; analytics numbers steps by it. */
const canonicalSteps = (): OnboardingSteps => [
    ...ONBOARDING_QUESTIONS.map((question) => question.id),
    ...FIXED_STEPS,
]

export const stepIndex = (step: OnboardingStep) => canonicalSteps().indexOf(step)

export const isOnboardingStep = (value: string): value is OnboardingStep =>
    canonicalSteps().includes(value as OnboardingStep)

/** The enabled questions in registry order, then the fixed steps. */
export const onboardingSteps = (): OnboardingSteps => [
    ...ONBOARDING_QUESTIONS.filter((question) => question.enabled).map((question) => question.id),
    ...FIXED_STEPS,
]

/** The shown step after `step`. */
export const nextStep = (step: OnboardingStep, steps: OnboardingSteps): OnboardingStep =>
    steps[steps.indexOf(step) + 1] ?? step

/** The gallery's focused panel: a blank start, one template, or (`null`) the list alone. */
export type GalleryFocus = {kind: "scratch"} | {kind: "template"; key: string} | null

/** Where the flow is, as its URL says: `/onboarding/<step>[/<template key | scratch>]`. */
export type OnboardingRoute =
    | {step: Exclude<OnboardingStep, "templates">}
    | {step: "templates"; focus: GalleryFocus}

const SCRATCH = "scratch"

export const stepRoute = (step: OnboardingStep): OnboardingRoute =>
    step === "templates" ? {step, focus: null} : {step}

/** The route a path's segments name, or `null` when they name none (the bare page resumes). */
export const parseOnboardingRoute = (segments: readonly string[]): OnboardingRoute | null => {
    const [step, detail, ...rest] = segments
    if (rest.length > 0 || step === undefined || !isOnboardingStep(step)) return null
    if (step === "templates") {
        if (!detail) return {step, focus: null}
        return {
            step,
            focus: detail === SCRATCH ? {kind: "scratch"} : {kind: "template", key: detail},
        }
    }
    return detail === undefined ? {step} : null
}

/** The path after `/onboarding`, without a leading slash. */
export const onboardingRoutePath = (route: OnboardingRoute): string => {
    if (route.step !== "templates" || !route.focus) return route.step
    const detail = route.focus.kind === "scratch" ? SCRATCH : encodeURIComponent(route.focus.key)
    return `templates/${detail}`
}

type Answers = Pick<OnboardingDraft, "answers">

/** A later step opens once every shown question before it is answered. */
export const isStepOpen = (step: OnboardingStep, draft: Answers, steps: OnboardingSteps) => {
    const at = steps.indexOf(step)
    if (at < 0) return false
    return steps
        .slice(0, at)
        .every((earlier) => isFixedStep(earlier) || answerLabels(draft.answers[earlier]).length > 0)
}

/** The latest step the answers open, for a link to a step the user has not reached. */
const furthestOnboardingRoute = (answers: Answers, steps: OnboardingSteps): OnboardingRoute =>
    stepRoute(steps.findLast((step) => isStepOpen(step, answers, steps)) ?? steps[0])

/** The requested route when the answers open it, else the furthest one they do. */
