import {fetchProfile} from "@agenta/entities/profile"
import {useSetAtom} from "jotai"
import {useRouter} from "next/router"

import {postAuthBootAtom} from "@/features/app/postAuthBoot"
import {markOnboardingPending} from "@/features/onboarding/onboardingPending"
import {writeLastAuthEmail, writeLastAuthMethod} from "@/lib/auth"
import {queryClient} from "@/lib/queryClient"

export interface AuthSuccess {
    /** "email" for password and one-time code, else the OIDC provider id. */
    method: string
    /** The address an email method signed in with. */
    email?: string
    /** SuperTokens' `createdNewRecipeUser`; account linking is off, so it means a new login. */
    isNewUser: boolean
}

/**
 * A new account owes onboarding; the mark is keyed by the Agenta user id the app reads later.
 * When the profile cannot load yet, an unowned mark stands in until Home reads the user.
 */
const markNewAccount = async () => {
    const user = await queryClient
        // Reuses the profile the sign-in just refetched; an invalidated one is still fetched.
        .fetchQuery({queryKey: ["profile"], queryFn: fetchProfile, staleTime: 30_000})
        .catch(() => null)
    markOnboardingPending(user?.id ?? null)
}

/** Every successful sign-in: remember the method, raise the loader, refetch, go home. */
export function useAuthSuccess() {
    const router = useRouter()
    const startBoot = useSetAtom(postAuthBootAtom)
    return useCallback(
        async ({method, email, isNewUser}: AuthSuccess) => {
            writeLastAuthMethod(method)
            if (method === "email" && email) writeLastAuthEmail(email)
            startBoot({account: isNewUser ? "new" : "returning", startedAt: Date.now()})
            try {
                await Promise.all([
                    queryClient.invalidateQueries({queryKey: ["profile"]}),
                    queryClient.invalidateQueries({queryKey: ["mobile", "projects"]}),
                ])
                if (isNewUser) await markNewAccount()
                await router.replace("/")
            } catch (error) {
                startBoot(null)
                throw error
            }
        },
        [router, startBoot],
    )
}
/**
 * Where the auth gate should send you, given the session verdict and where you are.
 *
 * Split out as a pure function because the interesting part is the SYMMETRY, and that is what
 * regressed: the gate only ever routed one way. A signed-out session was sent to /auth, but a
 * session that turned out to be fine while you sat there had nothing to send you back — and the
 * gate stopped re-checking on /auth, so the verdict could never be revisited. A transient 401
 * (a backend that is up but not yet serving, a refresh that raced) therefore stranded a perfectly
 * valid session on the sign-in page until a manual navigation or a hard reload.
 */
export type SessionVerdict = "ok" | "unauthenticated" | "unknown"

/** The OIDC callback completes the sign-in itself; forwarding out of it would abort the exchange. */
const isCallbackRoute = (pathname: string) => pathname.startsWith("/auth/callback")

const isAuthRoute = (pathname: string) => pathname.startsWith("/auth")

/** The route to replace with, or null to stay put. */
export const authRedirectTarget = (verdict: SessionVerdict, pathname: string): string | null => {
    if (isCallbackRoute(pathname)) return null
    if (verdict === "unauthenticated") return isAuthRoute(pathname) ? null : "/auth"
    // A confirmed session while sitting on the sign-in page: hand back to the root resolver, which
    // knows the remembered workspace/project pair. Only from a CONFIRMED verdict — "unknown" is
    // the first load, before any answer, and must not move anyone.
    if (verdict === "ok") return isAuthRoute(pathname) ? "/" : null
    return null
}

/** Whether the gate should be asking at all. It must keep asking on /auth — that is the only way a
 * stale or wrong verdict gets corrected — but never during the callback exchange. */
export const shouldCheckSession = (pathname: string) => !isCallbackRoute(pathname)
        queryFn: () => fetchProjects(),
        enabled,
        staleTime: 30_000,
        // Overrides this app's `refetchOnWindowFocus: false` default, for this query only. It is
        // the gate's ONLY re-check trigger: staleTime does not schedule anything, and with the
        // default off a wrong verdict had no way at all to be revisited — a hard reload was the
        // only escape. Coming back to the tab now re-asks.
        refetchOnWindowFocus: true,
    })

    const verdict: SessionVerdict =
        data?.kind === "unauthenticated"
            ? "unauthenticated"
            : data?.kind === "ok"
              ? "ok"
              : "unknown"
    const target = authRedirectTarget(verdict, router.pathname)
    useEffect(() => {
        // Sign-in drops the query; the root resolver picks the template key back up after it.
        if (target === "/auth" && typeof router.query.template === "string") {
            rememberTemplateKey(router.query.template)
        }
        if (target) void router.replace(target)
